    return _clean(_call(node[1], node[2], sheet))


def _top(node, sheet):
    v = _ev(node, sheet)
    return 0 if v is None else v


def evaluate(src, cells=None):
    node = parse(src)
    sheet = cells if isinstance(cells, Sheet) else Sheet(cells or {})
    return _top(node, sheet)

