    def __init__(self, toks):
        self.toks = toks
        self.i = 0

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else (None, None)

    def take(self):
        t = self.peek()
        self.i += 1
        return t

    def accept(self, *ops):
        kind, val = self.peek()
        if kind == "op" and val in ops:
            self.i += 1
            return val
        return None

    def expect(self, op):
        if not self.accept(op):
            raise ValueError("expected %r" % op)

    def expr(self):
        node = self.add()
        while True:
            op = self.accept("=", "<>", "<=", ">=", "<", ">")
            if not op:
                return node
            node = ("bin", op, node, self.add())

    def add(self):
        node = self.mul()
        while True:
            op = self.accept("+", "-")
            if not op:
                return node
            node = ("bin", op, node, self.mul())

    def mul(self):
        node = self.unary()
        while True:
            op = self.accept("*", "/")
            if not op:
                return node
            node = ("bin", op, node, self.unary())

    def unary(self):
        if self.accept("-"):
            return ("neg", self.unary())
        if self.accept("+"):
            return self.unary()
        return self.power()

    def power(self):
        node = self.primary()
        if self.accept("^"):
            return ("bin", "^", node, self.unary())
        return node

    def primary(self):
        kind, val = self.take()
        if kind == "num":
            return ("num", val)
        if kind == "ref":
            if self.accept(":"):
                k2, v2 = self.take()
                if k2 != "ref":
                    raise ValueError("range needs a reference after ':'")
                return ("range", val, v2)
            return ("ref", val)
        if kind == "name":
            if val not in _ARITY:
                raise ValueError("unknown function: %s" % val)
            self.expect("(")
            args = []
            if not self.accept(")"):
                args.append(self.expr())
                while self.accept(","):
                    args.append(self.expr())
                self.expect(")")
            lo, hi = _ARITY[val]
            if len(args) < lo or (hi is not None and len(args) > hi):
                raise ValueError("wrong number of arguments for %s" % val)
            return ("call", val, args)
        if kind == "op" and val == "(":
            node = self.expr()
            self.expect(")")
            return node
