import math
import re


class CalcError(str):
    pass


DIV0 = CalcError("#DIV/0!")
VALUE = CalcError("#VALUE!")
CYCLE = CalcError("#CYCLE!")
REF = CalcError("#REF!")
SYNTAX = CalcError("#SYNTAX!")

_TOKEN = re.compile(
    r"\s*(?:(?P<num>\d+(?:\.\d+)?|\.\d+)"
    r"|(?P<ref>[A-Za-z][0-9]+)(?![A-Za-z0-9_(])"
    r"|(?P<name>[A-Za-z_][A-Za-z0-9_]*)"
    r"|(?P<op><>|<=|>=|[-+*/^(),:=<>]))"
)
_REF = re.compile(r"([A-Za-z])([0-9]+)")
_NUMBER = re.compile(r"[-+]?\d+(?:\.\d+)?")
_ARITY = {"SUM": (1, None), "AVG": (1, None), "MIN": (1, None), "MAX": (1, None), "COUNT": (1, None),
          "IF": (3, 3), "ABS": (1, 1), "ROUND": (2, 2)}


def _norm_ref(text):
    m = _REF.fullmatch(text)
    if not m:
        raise ValueError("bad reference: %r" % text)
    return m.group(1).upper() + str(int(m.group(2)))


def tokenize(src):
    out = []
    pos = 0
    while True:
        if src[pos:].strip() == "":
            return out
        m = _TOKEN.match(src, pos)
        if not m:
            raise ValueError("unexpected character at %d" % pos)
        pos = m.end()
        if m.group("num") is not None:
            t = m.group("num")
            out.append(("num", float(t) if "." in t else int(t)))
        elif m.group("ref") is not None:
            out.append(("ref", _norm_ref(m.group("ref"))))
        elif m.group("name") is not None:
            out.append(("name", m.group("name").upper()))
        else:
            out.append(("op", m.group("op")))


class _Parser:
    def __init__(self, toks):
        self.toks = toks
        self.i = 0

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else (None, None)

    def take(self):
        t = self.peek()
        self.i += 1
        return t

    def accept(self, *ops):
        kind, val = self.peek()
        if kind == "op" and val in ops:
            self.i += 1
            return val
        return None

    def expect(self, op):
        if not self.accept(op):
            raise ValueError("expected %r" % op)

    def expr(self):
        node = self.add()
        while True:
            op = self.accept("=", "<>", "<=", ">=", "<", ">")
            if not op:
                return node
            node = ("bin", op, node, self.add())

    def add(self):
        node = self.mul()
        while True:
            op = self.accept("+", "-")
            if not op:
                return node
            node = ("bin", op, node, self.mul())

    def mul(self):
        node = self.unary()
        while True:
            op = self.accept("*", "/")
            if not op:
                return node
            node = ("bin", op, node, self.unary())

    def unary(self):
        if self.accept("-"):
            return ("neg", self.unary())
        if self.accept("+"):
            return self.unary()
        return self.power()

    def power(self):
        node = self.primary()
        if self.accept("^"):
            return ("bin", "^", node, self.unary())
        return node

    def primary(self):
        kind, val = self.take()
        if kind == "num":
            return ("num", val)
        if kind == "ref":
            if self.accept(":"):
                k2, v2 = self.take()
                if k2 != "ref":
                    raise ValueError("range needs a reference after ':'")
                return ("range", val, v2)
            return ("ref", val)
        if kind == "name":
            if val not in _ARITY:
                raise ValueError("unknown function: %s" % val)
            self.expect("(")
            args = []
            if not self.accept(")"):
                args.append(self.expr())
                while self.accept(","):
                    args.append(self.expr())
                self.expect(")")
            lo, hi = _ARITY[val]
            if len(args) < lo or (hi is not None and len(args) > hi):
                raise ValueError("wrong number of arguments for %s" % val)
            return ("call", val, args)
        if kind == "op" and val == "(":
            node = self.expr()
            self.expect(")")
            return node
        raise ValueError("unexpected token")


def parse(src):
    p = _Parser(tokenize(src))
    if not p.toks:
        raise ValueError("empty formula")
    node = p.expr()
    if p.i != len(p.toks):
        raise ValueError("unexpected trailing tokens")
    return node


